export function encodeHeaderVal(val: any): string {
    return val.replace(/./g, function(c) {
        return c.charCodeAt(0) < 128 ? c : `\\x${c.charCodeAt(0).toString(16)}`;
    });
}

function setGaSessionDimension(newObj: Record<string, any>) {
    window.ga('set', newObj);
    // gtag doesn't have a way of setting session scoped cusotm dimansions,
    // so we have to keep our own list.
    Object.assign(window.gaSessionDimensions, newObj);
}


type GAEventParams = {
    name?: string;
    category?: string;
    action?: string;
    label?: string;
    value?: string|number|boolean;
};
function gaEvent({name, category, action, label, value}: GAEventParams) {
    window.ga('send', 'event', {
        eventName: name,
        eventCategory: category,
        eventAction: action,
        eventLabel: label,
        eventValue: value,
    });
}

type GATimingParams = {
    name: string;
    category: string;
    value: number;
};
function gaTiming({category, name, value}: GATimingParams) {
    window.gtag('event', 'timing_complete', {
        event_category: category,
        name,
        value,
        ...window.gaSessionDimensions,
    });
}

