/**
 * Make a best effort to disbale naviagtion gestures and prompt users before
 * navigating away.
 */
export function discouragePageNavigation(message?: string): Function {
    message = message || 'Are you sure you want to leave this page?';
    /**
     * This isn't always honored by all browsers. It gets fired when a browser
     * unloads* resources, but not during SPA nav.
     */
    function attemptToPreventPageNavigation(event: Event): string {
        event.preventDefault();
        // The spec says this can be any truthy value, including a string which
        // can be displayed to the user. tsc complains that this has to be a
        // boolean.
        (event.returnValue as unknown as string) = message;
        return message;
    }

    window.addEventListener('beforeunload', attemptToPreventPageNavigation);
    // NOTE Safari equivalent to 'beforeunload'
    window.addEventListener('pagehide', attemptToPreventPageNavigation);
    // Prevents pull down reload behavior. Doesn't work on Safari or iOS Chrome.
    if (htmlElement) {
        htmlElement.style.overscrollBehavior = 'contain';
    }

    return function unlisten() {
        window.removeEventListener(
            'beforeunload', attemptToPreventPageNavigation);
        window.removeEventListener(
            'pagehide', attemptToPreventPageNavigation);
        if (htmlElement) {
            htmlElement.style.overscrollBehavior = '';
        }
    };
}

/**
 * Returns false if:
 * 1. gif has geo restricitons and we're on the server side.
 * 2. gif has geo restricitons, we're on the client side, but country is
 * unknown.
 * 3. gif has geo restricitons, we're on the client side, but country is
 * incompatible.
 */
export function gifCountryAllowed(
    gif: api.Post, context: jsx.AppGlobals): boolean {
    if (gif?.geographic_restriction) {
        if (!process.env.BROWSER) {
            return false;
        }
        if (!context.countryCode) {
            return false;
        }
        const countryMatch = gif.geographic_restriction.countries.includes(
            context.countryCode);
        if (gif.geographic_restriction.type === 'allow' && !countryMatch) {
            return false;
        }
        if (gif.geographic_restriction.type === 'block' && countryMatch) {
            return false;
        }
    }
    return true;
}

export function promiseSingleton(func: Function): Function {
    const promises: Record<string, Promise<any>> = {};
    return function promiseSingletonInner(...args) {
        const key = args.join('-');
        let promise = promises[key];
        if (!promise) {
            promise = promises[key] = func(...args).finally((val) => {
                delete promises[key];
            });
        }
        return promise;
    };
}

export function isPromise(obj: any): boolean {
    return obj && typeof obj.then === 'function';
}

export function addAuthorizationHeaderIfPresent(
    headers: Headers, token: string) {
    if (token) {
        headers.set('authorization', `Bearer ${token}`);
    }
}

const GIF_CONFIG_ID = '49';
const PROFILE_CONFIG_ID = '52';

/**
 *
 * @param {string} configId Reporting Widget config ID
 * @param {string} cid Content ID/URL
 * @param {boolean} redirect Whether to redirect or open in new tab. Useful for
 * getting around browser restrictions on opening new tabs.
 */
export function reportContentViaReportingWidget(
    configId: string, cid: string, redirect: boolean) {
    const params = new URLSearchParams({cid, url: cid});
    const url = `https://reportingwidget.google.com/widget/${configId}?${params.toString()}`;
    if (redirect) {
        window.location.href = url;
    } else {
        const windowProxy = window.open(url, '_blank');
        if (windowProxy) {
            // Focus on the new window if successful.
            windowProxy.focus();
        } else {
            // The popup/tab was blocked, so redirect anyway.
            window.location.href = url;
        }
    }
}

/**
 *
 * @param {string} cid Content ID/URL
 * @param {boolean} redirect Whether to redirect or open in new tab. Useful for
 * getting around browser restrictions on opening new tabs.
 */
export function reportGifViaReportingWidget(cid: string, redirect: boolean) {
    return reportContentViaReportingWidget(GIF_CONFIG_ID, cid, redirect);
}

/**
 *
 * @param {string} cid Content ID/URL
 * @param {boolean} redirect Whether to redirect or open in new tab. Useful for
 * getting around browser restrictions on opening new tabs.
 */
export function reportProfileViaReportingWidget(
    cid: string, redirect: boolean) {
    return reportContentViaReportingWidget(PROFILE_CONFIG_ID, cid, redirect);
}

export function getPageType(context: jsx.AppGlobals): string|undefined {
    const path = context.gtService.delocalizeUrlPath(
        context.router.history.location.pathname);
    if (path === '/') {
        return 'featured';
    } else if (path.match(/\/search\//)) {
        return 'search';
    } else if (path.match(/\/users\//) || path.match(/\/official\//)) {
        return 'profile';
    } else if (path.match(/\/view\//)) {
        return 'related';
    }
    return;
}

type GifEventParams = {
    viewindex: number;
    rid: string;
    category: string|undefined;
    searchfilter: string;
    tag?: string;
};

export function getGifEventParams(context: jsx.AppGlobals, viewindex: number,
    gif: api.Post): GifEventParams {
    const params: GifEventParams = {
        viewindex,
        rid: gif.id,
        category: getPageType(context),
        searchfilter: gif.searchfilter,
    };
    if (params.category === 'search' ) {
        const searchTerms = context.gtService.parseURLSearchTags(
            context.router.history.location.pathname).join(' ');
        params.tag = searchTerms;
    } else if (params.category === 'profile' && gif.user?.username) {
        params.tag = `@${gif.user.username}`;
    }
    return params;
}

/**
 * This includes legacy usernames that can include unicode characters. New
 * usernames should be ASCII only (`^[A-Za-z0-9_]{2,32}$`).
 */
export function isValidUsername(username: string): boolean {
    return Boolean(username.match(/^\S{2,32}$/u));
}

