import 'core-js/stable';

import 'console-polyfill';

function noop() {

}

if (process.env.BROWSER) {
    if (typeof global.window !== 'undefined') {
        // requires window, don't do this in webworker
        import('custom-event-polyfill');
    }

    if (typeof Element !== 'undefined') {
        // Later: check if these are supported by core-js.
        if (!Element.prototype.remove) {
            Element.prototype.remove = function removePolyfill() {
                if (this.parentNode) {
                    this.parentNode.removeChild(this);
                }
            };
        }
    }
}

function assertExists(name: string) {
    if (!(name in global)) {
        throw new Error(`${name} does not exist`);
    }
}

assertExists('Promise');
assertExists('URLSearchParams');


if (typeof global.document === 'undefined') {
    // Have to assign to `global`, any other method causes errors.
    // @ts-expect-error: mocking the whole Document isn't practical.
    global.document = {};
    global.document.addEventListener = noop;
}
if (typeof global.window === 'undefined') {
    global.window = {
        // @ts-expect-error: mocking the whole Navigator isn't practical.
        navigator: {
            userAgent: '',
        },
    };
    global.window.addEventListener = noop;
}

export const document = global.document;
export const window = global.window;
