import {Component} from 'inferno'; // eslint-disable-line @typescript-eslint/no-unused-vars
import {CustomComponent} from '../components';

import './ProgressCircle.scss';

export class ProgressCircle extends CustomComponent {
    radius: number;
    circumference: number;
    transitionTime: number;
    time?: number;

    constructor(props: jsx.Props, context: jsx.AppGlobals) {
        super(props, context);
        this.radius = this.props.radius - (this.props.thickness * 2);
        this.circumference = this.radius * 2 * Math.PI;
        this.transitionTime = 0;
    }

    componentDidUpdate(prevProps: jsx.Props) {
        if (this.props.smoothing) { // Smoothing: works best when progress is linear
            if (this.props.progress !== prevProps.progress) {
                if (!this.time) {
                    this.time = Date.now();
                } else {
                    const prevTime = this.time;
                    this.time = Date.now();
                    this.transitionTime = this.time - prevTime;
                }
            }
        }
    }

    render() {
        const {radius, thickness, color, progress} = this.props;

        return (
            <svg
                height={radius * 2}
                width={radius * 2}
            >
                <circle
                    stroke={color}
                    fill="transparent"
                    strokeWidth={thickness}
                    strokeDasharray={`${this.circumference} ${
                        this.circumference}`}
                    style={{
                        'stroke-dashoffset': (this.circumference) - (progress *
                            this.circumference),
                        'transition': `stroke-dashoffset ${this.transitionTime}ms`,
                        'transform': 'rotate(-90deg)',
                        'transform-origin': '50% 50%',
                    }}
                    r={this.radius}
                    cx={radius}
                    cy={radius}
                />
            </svg>
        );
    }
}

export class ProgressCircleIndeterminate extends CustomComponent {
    radius: number;

    constructor(props: jsx.Props, context: jsx.AppGlobals) {
        super(props, context);
        this.radius = (100 * (1 - props.strokeWidthRatio)) / 2;
    }

    render() {
        const {
            diameter,
            strokeWidthRatio,
            color,
            animationDuration,
        } = this.props;
        const diameterStr = `${diameter}px`;

        return (
            <div
                className="ProgressCircleIndeterminate"
                style={{
                    'height': diameterStr,
                    'width': diameterStr,
                    'animation-duration': `${animationDuration}ms`,
                }}
            >
                <svg
                    focusable="false"
                    preserveAspectRatio="xMidYMid meet"
                    viewBox={`0 0 100 100`}
                    style={{
                        'width': diameterStr,
                        'height': diameterStr,
                    }}
                >
                    <circle
                        cx="50%"
                        cy="50%"
                        r={this.radius}
                        className="ng-star-inserted"
                        style={{
                            'animation-name': `mat-progress-spinner-stroke-rotate-100`,
                            'stroke-dasharray': `282.743px`,
                            'stroke-width': `${strokeWidthRatio * 100}%`,
                            'stroke': color,
                        }}
                    ></circle>
                </svg>
            </div>
        );
    }
}
