import {autobind} from 'core-decorators';

import {Component} from 'inferno'; // eslint-disable-line @typescript-eslint/no-unused-vars

import {window} from '../../common/util';

import './ToggleMenu.scss';


export class ToggleMenu extends Component<jsx.Props, jsx.State> {
    lastEvent: Event|null;

    constructor(props: jsx.Props, context: jsx.AppGlobals) {
        super(props, context);
        this.state = {active: false};
        this.lastEvent = null;
        this.handleNewProps(props, this.state);
    }
    componentWillUpdate(nextProps: jsx.Props, nextState: jsx.State) {
        if (nextProps.menu !== this.props.menu) {
            this.handleNewProps(nextProps, nextState);
        }
    }
    handleNewProps(props: jsx.Props, state: jsx.State) {
        if (props.menu.props === null) {
            props.menu.props = {};
        }
        props.menu.className = `${props.menu.className || ''} ToggleMenu-ChildMenu`;
    }
    componentDidMount() {
        window.addEventListener('click', this.deactivate);
        if (this.props.closeOnScroll) {
            window.addEventListener('scroll', this.deactivate);
        }
    }
    componentWillUnmount() {
        window.removeEventListener('click', this.deactivate);
        if (this.props.closeOnScroll) {
            window.removeEventListener('scroll', this.deactivate);
        }
    }
    @autobind
    deactivate(event: Event) {
        if (this.lastEvent !== event) {
            this.setState({active: false});
        }
        this.lastEvent = event;
    }
    @autobind
    clickToggle(event: Event) {
        event.stopPropagation();
        if (this.lastEvent !== event) {
            this.setState({active: !this.state.active});
        }
        this.lastEvent = event;
        if (this.props.onClick) {
            this.props.onClick(event);
        }
    }

    render() {
        let className = `${this.props.className || ''} ToggleMenu`;
        let buttonClassName = `${this.props.buttonClassName || ''} ToggleMenu-button`;
        if (this.state.active) {
            className += ' clicked active';
            buttonClassName += ' clicked active';
        }
        return (
            <span className={className}>
                <span className={buttonClassName} onClick={this.clickToggle} >
                    { this.props.children }
                </span>
                {this.props.menu}
            </span>
        );
    }
}
