import {autobind} from 'core-decorators';
import debug from 'debug';

import {DataSource} from '../../replete';
import {addAuthorizationHeaderIfPresent, isPromise, isStatic, isSticker} from './util';
import emitter from './util/emitter';
import type {ResponseAndBody} from './services/apiService';

const LIMIT = 50;

export const SEARCHFILTERS = {
    all: 'none',
    gifs: undefined,
    stickers: 'sticker',
    memes: 'static,-sticker',
};

export class MyDataSource extends DataSource {
    declare store: app.MyStore;
    console: app.MyStore['console'];

    constructor(store: app.MyStore, path: string) {
        super(store, path);
        this.console = store.console.addIdentifier({
            component: `replete:DataSource:${path}`,
        });
    }
}

export class AuthDataSource extends MyDataSource {
    constructor(store: app.MyStore, path: string) {
        super(store, path);
        emitter.on('authDataSet', this.eventHandler);
    }
    destruct() {
        super.destruct();
        emitter.off('authDataSet', this.eventHandler);
    }
    @autobind
    eventHandler() {
        const authData = this.store.authService.authData;
        const pending = this.store.authService.pending;
        this.console.debug('eventHandler', {authData, pending});
        this.set([], {
            authData,
            pending,
        });
    }
    getInitial(keyArgs) {
        const authData = this.store.authService.authData;
        const pending = this.store.authService.pending;
        return {
            authData,
            pending,
        };
    }
}


export class AppConfigDataSource extends MyDataSource {
    constructor(store: app.MyStore, path: string) {
        super(store, path);
        emitter.on('appConfigFetched', this.eventHandler);
    }
    destruct() {
        super.destruct();
        emitter.off('appConfigFetched', this.eventHandler);
    }
    @autobind
    eventHandler(event) {
        const [anonid, body] = event.detail;
        this.console.debug('appConfigFetched eventHandler', anonid, body);
        body.loaded = true;
        body.pending = false;
        this.set([anonid], body);
    }
    clean(val) {
        if (!isPromise(val.promise)) {
            val.promise = Promise.resolve(val);
        }
        return val;
    }
    key([anonid]) {
        return anonid;
    }
    isValidKeyArgs([anonid]) {
        return typeof anonid === 'string' || anonid instanceof String;
    }
    callApi() {
        return this.store.apiService.getAppConfig();
    }
    getData([anonid], currentVal) {
        currentVal.pending = true;
        this.set([anonid], currentVal);

        return this.callApi().then(({body, response}) => {
            body.loaded = true;
            body.pending = false;
            body.promise = Promise.resolve(body);
            this.set([anonid], body);
            return body;
        }, ({body, response}) => {
            body = body || currentVal;
            body.pending = false;
            body.status = response ? response.status : 0;
            body.promise = Promise.reject(body);
            this.set([anonid], body);
            return body;
        });
    }
    getInitial([anonid]) {
        const val = {
            pending: false,
            promise: null,
            flags: [],
        };
        this.store.request.console.debug('AppConfigDataSource getInitial', val);
        if (process.env.BROWSER && this.isValidKeyArgs([anonid])) {
            val.pending = true;
            val.promise = this.store.monitor(this.getData([anonid], val));
        } else {
            val.promise = Promise.resolve(val);
        }
        this.clean(val);
        return val;
    }
}


