export class NotificationsDataSource extends MyDataSource {
    constructor(store: app.MyStore, path: string) {
        super(store, path);
        emitter.on('clearPendingNotificationsCount',
            this.clearPendingNotificationsCount);
        emitter.on('refreshNotifications', this.refresh);
    }
    destruct() {
        super.destruct();
        emitter.off('clearPendingNotificationsCount',
            this.clearPendingNotificationsCount);
        emitter.off('refreshNotifications', this.refresh);
    }
    @autobind
    refresh() {
        this.console.debug('refresh');
        const authService = this.store.authService;
        if (authService.isLoggedIn()) {
            this.getInitial([]);
        }
    }
    @autobind
    clearPendingNotificationsCount() {
        const val = {...this.get([])};
        this.set([], val);
    }
    key(keyArgs) {
        return '';
    }
    isValidKeyArgs(keyArgs) {
        return true;
    }
    callApi(next: string) {
        return this.store.apiService.getV2Notifications(next);
    }
    getData(currentVal) {
        this.set([], currentVal);

        return this.callApi(currentVal.next).then(({body, response}) => {
            // `pending`` is not present on v2, need to fake it on front end.
            let newPending = 0;
            const newNotifications = body.notifications || [];
            const oldNotifications = currentVal.notifications;
            const lastFetchedTS = oldNotifications[0]?.timestamp;

            // Set pending flag on new notifications. Also set html.
            for (let i = 0; i < newNotifications.length; i++) {
                if (lastFetchedTS &&
                    newNotifications[i].timestamp > lastFetchedTS) {
                    newNotifications[i].pending = true;
                    newPending++;
                } else {
                    break;
                }
            }

            body.notifications = [].concat(oldNotifications, newNotifications);
            body.pending = newPending + currentVal.pending;

            this.set([], body);
            return body;
        }, ({body, response}) => {
            this.set([], currentVal);
            return body;
        });
    }
    more(keyArgs) {
        const currentVal = this.get(keyArgs);
        if (currentVal.next) {
            this.getData(currentVal);
        }
    }
    getInitial(keyArgs) {
        const oneWeekAgo = 7 * 24 * 60 * 60;
        const val = {
            pending: 0,
            notifications: [],
            promise: null,
        };
        this.set([], val);
        const authService = this.store.authService;
        if (authService.isLoggedIn()) {
            if (this.isValidKeyArgs([])) {
                val.promise = this.store.monitor(this.getData(val));
            }
        }
        return val;
    }
}

export class TagsDataSource extends MyDataSource {
    key([type]) {
        return type;
    }
    getInitial([type]) {
        const val = {
            pending: true,
            tags: [],
            promise: null,
        };
        this.set([type], val);

        if (type) {
            const p = this.store.apiService.getV2<api.CategoryListBody>(
                '/categories', {type, contentfilter: 'high'});
            val.promise = this.store.monitor(p.then(({body, response}) => {
                const newBody = {
                    ...body,
                    pending: false,
                    tags: body.tags || [],
                    promise: null,
                };
                newBody.promise = Promise.resolve(newBody);
                this.set([type], newBody);
                return newBody;
            }, ({body, response}) => {
                body = body || val;
                body.pending = false;
                body.promise = Promise.reject(body);
                this.set([type], body);
                return body;
            }));
        }
        return val;
    }
}


