export class ExploreTermsDataSource extends MyDataSource {
    key([tag]) {
        return tag;
    }
    getPrefix(tag) {
        return /^[a-z]$/.test(tag[0]) ? tag[0] : '-';
    }
    callApi([tag]) {
        const url = `https://static.tenor.com/exploreterms/${this.getPrefix(tag)}/${tag || '-'}.json`;
        return this.store.httpService.request({
            method: 'GET',
            url,
            params: undefined,
            headers: new Headers(),
        }).then((response) => {
            if (response.ok) {
                return response.text().then((text) => {
                    return {body: JSON.parse(text), response};
                });
            }
            return Promise.reject({body: null, response});
        }, (err) => {
            return Promise.reject({body: {error: err}, response: null});
        });
    }
    isValidKeyArgs([tag]) {
        return tag || tag === '' ? true : false;
    }
    getData(keyArgs, currentVal) {
        currentVal.pending = true;
        this.set(keyArgs, currentVal);

        return this.callApi(keyArgs)
            .then(({body, response}) => {
                body.loaded = true;
                body.pending = false;
                body.results = body.results || [];
                this.set(keyArgs, body);
                return body;
            }, ({body, response}) => {
                body = body || currentVal;
                body.pending = false;
                body.results = [];
                body.status = response ? response.status : 0;
                this.set(keyArgs, body);
                return body;
            });
    }
    getInitial([tag]) {
        const val = {
            loaded: false,
            pending: true,
            results: [],
        };
        if (this.isValidKeyArgs([tag])) {
            this.store.monitor(this.getData([tag], val));
        }
        return val;
    }
}


export class GifResultsDataSource extends MyDataSource {
    addCommonParams(params) {
        params['media_filter'] = this.store.apiService.mediaFilterStr;
        params['fields'] = this.store.apiService.postResultsFieldsStr;
        return params;
    }
    callApi(keyArgs: string[], pos: string): Promise<
        ResponseAndBody<api.PostListBody>> {
        return Promise.reject({
            body: {error: 'callApi not defined'},
            response: null,
        });
    }
    isValidKeyArgs(keyArgs) {
        return keyArgs[0] ? true : false;
    }
    getData(keyArgs, currentVal) {
        const pos = currentVal.next;

        currentVal.pending = true;
        this.set(keyArgs, currentVal);
        this.console.debug('getData', keyArgs, pos);

        return this.callApi(keyArgs, pos).then(({body, response}) => {
            body = this.clean((body as api.PostListBody));
            // NOTE (v2 API): next = "" when no more results
            if (body.next === '') {
                body.noMore = true;
            }
            body.loaded = true;
            body.pending = false;
            let idx = currentVal.results.length;
            for (const result of body.results) {
                result.index = idx;
                idx++;
            }
            body.results = currentVal.results.concat(body.results || []);
            this.set(keyArgs, body);
            return body;
        }, ({body, response}) => {
            body = body || currentVal;
            body = this.clean(body);
            body.noMore = true;
            body.pending = false;
            body.results = [];
            this.set(keyArgs, body);
            return body;
        });
    }
    clean(val) {
        val.results = val.results || [];
        if (!isPromise(val.promise)) {
            val.promise = Promise.resolve(val);
        }
        return val;
    }
    getBlankData() {
        return this.clean({
            loaded: false,
            pending: true,
            noMore: false,
            promise: null,
        });
    }
    getInitial(keyArgs) {
        const val = this.getBlankData();
        if (this.isValidKeyArgs(keyArgs)) {
            val.promise = this.store.monitor(this.getData(keyArgs, val));
        }
        this.set(keyArgs, val);
        return val;
    }
    more(keyArgs) {
        const currentVal = this.get(keyArgs);
        if (!currentVal.pending && !currentVal.noMore) {
            this.getData(keyArgs, currentVal);
        }
    }
}


