export class PacksDataSource extends GifResultsDataSource {
    clean(val) {
        val = super.clean(val);
        val.name = val.name || '';
        return val;
    }
    callApi([id], pos) {
        if (!id.match(/^[0-9a-z]+$/)) {
            return Promise.reject({
                body: {
                    error: `${id} is not a valid encrypted_v1_id`,
                    loaded: true,
                    pending: false,
                },
                response: null,
            });
        }
        const authService = this.store.authService;
        const googleAccessToken = authService.getGoogleAccessToken();

        const query = this.addCommonParams({
            encrypted_v1_id: id,
            limit: LIMIT,
        });
        const headers = new Headers();
        addAuthorizationHeaderIfPresent(headers, googleAccessToken);
        if (pos) {
            if (!Number.isInteger(pos)) {
                return Promise.reject({
                    body: {
                        error: `${pos} is not a valid pos`,
                    },
                    response: null,
                });
            }
            query.pos = pos;
        }
        return this.store.apiService.getV2<api.PostListBody>(
            '/collection_posts', query, headers);
    }
    key([id]) {
        const hasTenorScope = this.store.authService.hasTenorOAuthScope();
        return `${id}-${hasTenorScope || false}`;
    }
}


