export class BaseSearchDataSource extends GifResultsDataSource {
    baseCallApi(
        q: string,
        contentfilter: string,
        searchfilter: string,
        pos: string): Promise<ResponseAndBody<api.PostListBody>> {
        const query = this.addCommonParams({
            q,
            limit: LIMIT,
            contentfilter,
        });
        if (searchfilter) {
            query.searchfilter = searchfilter;
        }
        if (pos) {
            query.pos = pos;
        }
        return this.store.apiService.getSearch(query);
    }
}


export class UniversalSearchDataSource extends BaseSearchDataSource {
    callApi([q, contentfilter, universalSearchFormat],
        pos: string) {
        const searchfilter = SEARCHFILTERS[universalSearchFormat];
        return this.baseCallApi(
            q, contentfilter, searchfilter, pos);
    }
    key([q, contentfilter, universalSearchFormat]) {
        return `${q}-${contentfilter}-${universalSearchFormat}`;
    }
}


export class SearchGifsByUsernameDataSource extends GifResultsDataSource {
    callApi([username, section, ownsProfile], pos: string) {
        this.console.debug('callApi', {ownsProfile});
        let p;
        if (section === 'favorites') {
            return this.store.apiService.getUserLikedGifs(pos);
        } else {
            if (ownsProfile === true) {
                this.console.debug('returning user owned uploads');
                p = this.store.apiService.getBatchedListUploadsV2(pos);
            } else if (ownsProfile === false) {
                this.console.debug('returning public uploads');
                const query = this.addCommonParams({});
                if (pos) {
                    query.pos = pos;
                }
                query.q = `@${username}`;
                query.limit = LIMIT;
                p = this.store.apiService.getSearch(query);
            } else {
                this.console.debug('returning blank gifs body');
                return Promise.resolve({
                    body: this.getBlankData(),
                    response: null,
                });
            }
        }

        return p.then(({body, response}) => {
            body = {...body};
            body.results = [].concat(body.results).filter((result) => {
                return !isSticker(result) && !isStatic(result);
            });
            return {body, response};
        });
    }
    key([username, section, ownsProfile]) {
        let subKey = '';
        if (ownsProfile === true) {
            subKey = 'owned';
        } else if (ownsProfile === false) {
            subKey = 'public';
        } else {
            subKey = 'blank';
        }
        const k = `${username}-gifs-${section}-${subKey}`;
        // this.console.debug('key', k);
        return k;
    }
}


