export class ProfileDataSource extends MyDataSource {
    key([username, authedUsername]) {
        username = username.toLowerCase();
        const k = `${username}-${authedUsername || ''}`;
        return k;
    }
    getBlankData() {
        const val = {
            pending: true,
            user: {
                userid: '-1',
                username: '',
                partnername: '',
                partnercta: {url: '', text: ''},
                partnerlinks: [],
                usertype: 'user',
                tagline: '',
            },
            promise: null,
        };
        val.promise = Promise.resolve(val);
        return val;
    }
    clean(val) {
        val = {
            ...this.getBlankData(),
            ...val,
        };
        if (!isPromise(val.promise)) {
            val.promise = Promise.resolve(val);
        }
        return val;
    }
    getInitial([username, authedUsername]) {
        username = username.toLowerCase();
        const val = this.getBlankData();
        if (!username) {
            return val;
        }
        this.set([username, authedUsername], val);

        const query = {username};
        const headers = new Headers();

        let p;
        const refreshImageUrl = (url) => {
            // Sometimes these URLs may 404 or have a placeholder immediately
            // after uploading. We need to update them in place if they're on
            // the page, even if the access_token is the same.
            const els = document.body.querySelectorAll(`img[src='${url}']`);
            if (els.length) {
                fetch(url).then(() => {
                    els.forEach((img: HTMLImageElement) => {
                        img.src = url;
                    });
                });
            }
        };
        const ownsProfile = this.store.authService.ownsProfile(username);
        const googleAccessToken = this.store.authService.getGoogleAccessToken();
        if (googleAccessToken && ownsProfile) {
            addAuthorizationHeaderIfPresent(headers, googleAccessToken);
            p = this.store.apiService.getV2<api.UserSingleBody>(
                '/profile', query, headers);
        } else {
            p = this.store.apiService.getV2<api.UserSingleBody>(
                '/user', query);
        }
        p = p.then(({body, response}) => {
            if (process.env.BROWSER) {
                Object.values({
                    ...body.user.avatars,
                    ...body.user.partnerbanner,
                }).forEach((url: string) => {
                    url = this.store.apiService.addAuthToImgUrlIfV2(url);
                    refreshImageUrl(url);
                });
            }
            return {body, response};
        });

        val.promise = this.store.monitor(p.then(({body, response}) => {
            body.pending = false;
            body = this.clean(body);
            this.set([username, authedUsername], body);
            return body;
        }, ({body, response}) => {
            body = body || val;
            body.pending = false;
            body = this.clean(body);
            this.set([username, authedUsername], body);
            return body;
        }));
        return val;
    }
}
