const storageServiceKey = 'locale';

export function getChosenLocale(context: jsx.AppGlobals): string|null {
    const locale = context.storageService.getItem(storageServiceKey);
    if (locale && langOrLocaleIncluded(locale, langDirDenyList)) {
        return null;
    }
    return locale;
}

export function setChosenLocale(context: jsx.AppGlobals, chosenLocale: string) {
    context.storageService.setItem(storageServiceKey, chosenLocale);
}

