export function redirectToLang(context: jsx.AppGlobals, selectedLang: string) {
    const currentPath = context.gtService.delocalizeUrlPath(
        context.router.history.location.pathname);
    const localePrefix = selectedLang !== 'en' ?
        `/${selectedLang.replace('_', '-')}` : '';
    window.location.href = `${localePrefix}${currentPath}${
        context.router.history.location.search}`;
}

interface LanguageSearchBoxProps extends BaseSearchBoxProps {
    idx: number;
    languages: LocaleSuggestion[];
    langSelectionDialog: any;
}

export class LanguageSearchBoxValue implements BaseSearchUIValue {
    locale: LocaleSuggestion;

    constructor(locale) {
        this.locale = locale;
    }
    key() {
        return this.locale[0];
    }
    toUserString() {
        return `${this.locale[3]} / ${this.locale[2]}`;
    }
}

@subscribe({
    isMobile: ['ui.isMobile'],
})
export class LanguageSearchBox extends BaseSearchBox<
    LanguageSearchBoxValue, LanguageSearchBoxProps> {
    constructor(props: jsx.Props, context: jsx.AppGlobals) {
        super(props, context);
        this.dropdownEnabledOnFocus = true;
        this.focusAfterSelect = false;
        this.canAddSuggestion = false;
        this.scrollSuggestions = true;
    }
    componentDidMount() {
        if (!this.props.isMobile && this.props.idx === 0) {
            const s = '';
            this.setState({value: s});
            const reqValue = s;
            this.fetchSuggestions(reqValue).then((suggestions) => {
                this.defaultSuggestions = suggestions;
            });
        }
    }
    stringToValue(s: string): LanguageSearchBoxValue {
        for (const lang in this.props.languages) {
            if (lang[0] === s) {
                return new LanguageSearchBoxValue(lang);
            }
        }
        return new LanguageSearchBoxValue(['', '', '', '', '']);
    }
    fetchSuggestions(reqValue: string): Promise<LanguageSearchBoxValue[]> {
        // only update suggestions if search term === current search term
        if (reqValue === this.state.value.trim()) {
            const lowerReqValues = reqValue.toLowerCase().split(/\s+/);
            const suggestions = this.props.languages.filter((langItem) => {
                return lowerReqValues.every((lowerReqValue) => {
                    return langItem[4].includes(lowerReqValue);
                });
            });
            const first = [];
            const second = [];
            const remainder = [];
            for (const suggestion of suggestions) {
                if (suggestion[3].toLowerCase().startsWith(
                    lowerReqValues[0])) {
                    first.push(suggestion);
                } else if (suggestion[2].toLowerCase().startsWith(
                    lowerReqValues[0])) {
                    second.push(suggestion);
                } else {
                    remainder.push(suggestion);
                }
            }

            const sortedSuggestions = [
                ...first,
                ...second,
                ...remainder,
            ].map((locale) => {
                return new LanguageSearchBoxValue(locale);
            });
            this.setSuggestions(sortedSuggestions);
            return Promise.resolve(sortedSuggestions);
        }
        return Promise.resolve(this.defaultSuggestions);
    }
    onDone(suggestion: string) {
        this.props.langSelectionDialog.setState({
            selectedLocale: suggestion});
    }
    @autobind
    placeholder() {
        const gettextSub = this.context.gtService.gettextSub;

        // Translators: Search input placeholder text.
        return gettextSub('Search for Language');
    }
    getSuggestionListHeader(text: string): string {
        const gettextSub = this.context.gtService.gettextSub;

        return gettextSub('Suggested Language');
    }
    render() {
        console.log('this.state.value', this.state.value);
        const text = this.state.value;

        return <div
            className={`LanguageSearchBox BaseSearchBox${
                this.scrollSuggestions ? ' scrollable' : ''}`}>
            <div className="lang-input-wrapper">
                <input
                    ref={this.setInputElement}
                    id={`lang_${this.props.idx}`}
                    className="lang-input"
                    onInput={this.handleOnInput}
                    onBlur={this.handleOnBlur}
                    onFocus={this.handleOnFocus}
                    onKeyDown={this.handleOnKeyDown}
                    onMouseOver={this.clearSuggestionSelection}
                    onPaste={this.handlePaste}
                    value={text}
                    placeholder={this.placeholder()}
                    spellCheck={false}
                    autoCorrect={this.iOS ? 'off' : 'on'}
                    autoCapitalize="off"
                    autoComplete="off"
                />
            </div>
            { this.state.dropdownEnabled && this.state.focused &&
                this.renderSuggestionDropDown() }
        </div>;
    }
}

export class LanguageSelectionDialog extends CustomComponent {
    constructor(props: jsx.Props, context: jsx.AppGlobals) {
        super(props, context);
        const gtService = this.context.gtService;
        this.state = {
            ...this.state,
            selectedLocale: gtService.gt.locale,
        };
    }
    getSelectedLocaleTuple() {
        const {selectedLocale} = this.state;
        for (const locale of this.context.languages) {
            if (locale[0] === selectedLocale) {
                return locale;
            }
        }
        console.warn(`Selected locale ${selectedLocale} is missing from list.`);
    }
    @autobind
    onConfirm() {
        const selectedLocaleTuple = this.getSelectedLocaleTuple();
        const selectedLocale = selectedLocaleTuple ?
            selectedLocaleTuple[0] : 'en';
        setChosenLocale(this.context, selectedLocale);
        redirectToLang(this.context, selectedLocale);
    }
    render() {
        const gtService = this.context.gtService;
        const gettextSub = this.context.gtService.gettextSub;
        const gettextSubComponent = this.context.gtService.gettextSubComponent;

        const selectedLang = this.getSelectedLocaleTuple();
        const selectedLangLabel = selectedLang ?
            new LanguageSearchBoxValue(selectedLang).toUserString() :
            gettextSub('None');
        const isCurrentLocaleSelected = (
            this.state.selectedLocale === gtService.gt.locale);

        return (
            <div id="language-selection-dialog">
                <h2>{gettextSub('Language')}</h2>
                <LanguageSearchBox
                    languages={this.context.languages}
                    idx={0}
                    langSelectionDialog={this}
                />
                <h3>{gettextSub('Confirm language selection?')}</h3>
                <p>{
                    gettextSubComponent('You have selected {lang}',
                        {lang: <strong>{selectedLangLabel}</strong>})
                }</p>
                <p>{gettextSub(
                    'Clicking yes will reload Tenor in the language you have selected.',
                )}</p>
                <div className="button-row">
                    <Button
                        className="deny-button"
                        onClick={this.props.dialog.close}>
                        {gettextSub('No')}
                    </Button>
                    <Button
                        className="confirm-button"
                        onClick={this.onConfirm}
                        disabled={isCurrentLocaleSelected}>
                        {gettextSub('Yes')}
                    </Button>
                </div>
            </div>
        );
    }
}
