import * as cookie from 'cookie';

import {document} from '../util';


class InMemoryStorage {
    d: Record<string, string>;

    constructor() {
        this.d = {};
    }
    getItem(key: string): string|null {
        if (!(key in this.d)) {
            return null;
        }
        return this.d[key];
    }
    removeItem(key: string) {
        delete this.d[key];
    }
    setItem(key: string, value: any): string {
        return this.d[key] = `${value}`;
    }
    clear() {
        this.d = {};
    }
    get length() {
        return Object.keys(this.d).length;
    }
    key(i: number): string|null {
        const keys = Object.keys(this.d);
        return keys[i] || null;
    }
}


export function getStorageService(appGlobals: jsx.AppGlobals): Storage {
    let storage: Storage|undefined;

    if (typeof localStorage === 'object') {
        try {
            localStorage.setItem('localStorage', '1');
            localStorage.removeItem('localStorage');
            storage = localStorage as Storage;
        } catch (e) {
            appGlobals.request.console.error('localStorage not working');
        }
    } else {
        appGlobals.request.console.debug('localStorage does not exist');
    }

    if (!storage) {
        storage = new InMemoryStorage() as Storage;
    }

    try {
        // Test Support
        const initCookie = cookie.parse(
            document?.cookie || '').initLocalStorage;
        if (initCookie) {
            storage.clear();
            for (const [key, val] of Object.entries(JSON.parse(initCookie))) {
                storage.setItem(key, val as any);
            }
        }
    } catch (err) {
        appGlobals.request.console.error(err);
    }
    return storage;
}
