import {autobind} from 'core-decorators';

import {Component} from 'inferno'; // eslint-disable-line @typescript-eslint/no-unused-vars

import {subscribe} from '../../../replete';

import {CustomComponent} from '../../common/components';
import {FavButton} from '../../common/components/Icon';
import emitter from '../../common/util/emitter';


@subscribe({
    auth: ['api.auth'],
})
export class GifFavButton extends CustomComponent {
    constructor(props: jsx.Props, context: jsx.AppGlobals) {
        super(props, context);
        this.state = {
            ...this.state,
            animated: false,
        };
    }

    componentDidMount() {
        emitter.on('favoriteDataSet', this.triggerUpdate);
    }

    componentWillUnmount() {
        emitter.off('favoriteDataSet', this.triggerUpdate);
    }

    getSelected() {
        if (this.context.authService.isLoggedIn()) {
            return this.context.cacheService.isFavorite(this.props.gif);
        }
        return false;
    }

    @autobind
    toggle() {
        const selected = this.getSelected();
        console.log('GifFavButton.toggle', this.props.gif.id, selected);
        this.context.apiService.setFavorite({
            gif: this.props.gif,
            remove: selected,
        });
        if (!selected) {
            this.setState({animated: true});
            window.setTimeout(() => {
                this.setState({animated: false});
            }, 400);
        }
    }

    @autobind
    onClick() {
        const gettextSub = this.context.gtService.gettextSub;
        const authService = this.context.authService;
        if (authService.isLoggedIn()) {
            // Favoriting requires a linked account with the Tenor scope.
            if (authService.hasTenorOAuthScope()) {
                this.toggle();
            } else {
                // Need to refresh scope.
                authService.showScopeRefreshDialog({
                    permissionText: gettextSub('Before we can modify your favorites, you must grant Tenor the proper permissions on your Google Account.'),
                });
            }
        } else {
            authService.showLoginDialog();
        }
    }

    render() {
        const selected = this.getSelected();
        return <FavButton
            className={`GifFavButton${selected ? ' selected' : ''}${this.state.animated ? ' animated' : ''}`}
            onClick={this.onClick}
        />;
    }
}
