import {window} from './util';


type UserData = {
    TIMESTAMP: number;
    NUM: number;
};

export const generateMultivariateUserData = (
    context: jsx.AppGlobals): UserData => {
    const MV_USER_DATA = {
        NUM: Math.random(),
        TIMESTAMP: Date.now() / 1000,
    };
    context.storageService.setItem(
        'MV_USER_DATA', JSON.stringify(MV_USER_DATA));
    return MV_USER_DATA;
};

export const getUserNum = (context: jsx.AppGlobals): number => {
    const CONSTANTS = context.CONSTANTS;
    const query = new URLSearchParams(context.router.history.location.search);
    if (query.has('MV_USER_NUM')) {
        // Useful for dev/testing.
        return parseFloat(query.get('MV_USER_NUM'));
    } else {
        const MV_USER_DATA_STR = context.storageService.getItem('MV_USER_DATA');
        let MV_USER_DATA: UserData;
        if (!MV_USER_DATA_STR) {
            MV_USER_DATA = generateMultivariateUserData(context);
        } else {
            MV_USER_DATA = JSON.parse(MV_USER_DATA_STR);
            if (MV_USER_DATA.TIMESTAMP < CONSTANTS.MV_RESET_TIMESTAMP) {
                MV_USER_DATA = generateMultivariateUserData(context);
            }
        }
        return MV_USER_DATA.NUM;
    }
};

export const setupMultivariateTest = (context: jsx.AppGlobals,
    BROWSER: string|boolean|undefined, ga: Function) => {
    const CONSTANTS = context.CONSTANTS;
    let MV_USER_NUM = 0;
    if (BROWSER) {
        MV_USER_NUM = getUserNum(context);
    }

    const BUCKET_SIZE = 1 / CONSTANTS.MV_NUM_BUCKETS;

    // Groups are 1 indexed, which is less confusing for non-programmers.
    const groupNum = 1 + Math.floor(MV_USER_NUM * CONSTANTS.MV_NUM_BUCKETS);
    const groupName = `MV Group ${groupNum}/${CONSTANTS.MV_NUM_BUCKETS}`;
    context.request.console.debug({groupNum, groupName});
    context.multivariateGroup = groupNum;
    window.setGaSessionDimension({
        dimension2: groupName,
    });

    context.multivariateGroupSelect = (items: Record<string, any>,
        control?: any): any => {
        const noControl = control === undefined;
        if (process.env.NODE_ENV !== 'production') {
            if (!items) {
                throw new Error(`Items missing.`);
            }
            const itemsLen = Object.keys(items).length + (noControl ? 0 : 1);
            // Don't count control group.
            const percentageUnderTest = BUCKET_SIZE * (itemsLen - 1);
            if (percentageUnderTest > CONSTANTS.MV_DSFT_THRESHOLD) {
                throw new Error(
                    `Too many variations, an Ariane will be required: ${
                        itemsLen} items.`);
            }
        }
        return context.arianeMultivariateGroupSelect(items, control);
    };
    context.arianeMultivariateGroupSelect = (items: Record<string, any>,
        control?: any): any => {
        const noControl = control === undefined;
        const minRequiredKeys = noControl ? 2 : 1;
        if (process.env.NODE_ENV !== 'production') {
            if (!items) {
                throw new Error(`Items missing.`);
            }
            const keys = Object.keys(items);
            if (keys.length < minRequiredKeys) {
                throw new Error(`Invalid number of items: ${keys.length}.`);
            }
            for (const key of keys) {
                const castKey = parseFloat(key);
                // 1 doesn't always === Math.floor(1), but 1 == Math.floor(1)
                if (castKey < 1 || castKey > CONSTANTS.MV_NUM_BUCKETS ||
                    castKey != Math.floor(castKey)) { // eslint-disable-line eqeqeq
                    throw new Error(`${key} is invalid.`);
                }
            }
            if (keys.length < CONSTANTS.MV_NUM_BUCKETS && noControl) {
                throw new Error(`control is missing`);
            }
        }
        if (context.multivariateGroup in items) {
            return items[context.multivariateGroup];
        }
        if (!noControl) {
            return control;
        }
        throw new Error(
            `${context.multivariateGroup} not found, no control present.`);
    };
};
