import {autobind} from 'core-decorators';
import {Component} from 'inferno'; // eslint-disable-line @typescript-eslint/no-unused-vars
import {BaseSearchUI, BaseSearchUIProps, BaseSearchUIState, BaseSearchUIValue} from '../../../../common/components/BaseSearchBar';
import {subscribe} from '../../../../../replete';
import {ITEM_STATES} from '../constants';
import {KEY} from '../../../../common/constants';
import {iOS} from '../../../../common/util/isMobile';
import type UploadGifDataObject from './UploadGifDataObject';
import type {InfernoUIEvent} from 'inferno';

import './TagSearchBox.scss';


interface TagSuggestionProps<T extends BaseSearchUIValue> {
    idx: number;
    suggestion: T;
    selectedSuggestionIndex: number;
    searchBox: any;
}

function TagSuggestion<T extends BaseSearchUIValue>({
    idx, suggestion, searchBox, selectedSuggestionIndex,
}: TagSuggestionProps<T>,
context: jsx.AppGlobals) {
    const gettextSub = context.gtService.gettextSub;

    const highlighted = idx === searchBox.state.selectedSuggestionIndex;

    function handleMouseOver(event: Event) {
        searchBox.selectSuggestionByMouseOver(event, idx);
    }

    return (
        <div
            className={`Suggestion${highlighted ? ' selected' : ''}`}
            onMouseOver={
                // NOTE: iOS interprets a first tap event as mouseover,
                // requiring two taps to fire button onClick.
                searchBox.props.isMobile ? null : handleMouseOver
            }
        >
            <button
                className="term"
                onClick={(e) => searchBox.handleSuggestionSelect(e, idx)}
            >
                { suggestion.toUserString() }
            </button>

            { highlighted && searchBox.isApplicableToMultipleItems() &&
            <button
                className={`apply-all-button ${
                    searchBox.state.applyTagToAll ? ' selected' : ''}`}
                onClick={(e) => searchBox.handleSuggestionSelectAll(e, idx)}
            >
                {
                    // Translators: For adding tag suggestion to all GIFs.
                    gettextSub('Add to All')
                }
            </button>
            }
        </div>
    );
}

export interface BaseSearchBoxProps extends BaseSearchUIProps {
    taggingView?: any;
    isMobile?: boolean;
}

export interface BaseSearchBoxState<
    T extends BaseSearchUIValue> extends BaseSearchUIState<T> {
    applyTagToAll: boolean;
    dropdownEnabled: boolean;
    allowTagCreationOnInputBlur: boolean;
}

export abstract class BaseSearchBox<
    T extends BaseSearchUIValue,
    ChildSearchBoxProps extends BaseSearchBoxProps = BaseSearchBoxProps,
    ChildSearchBoxState extends BaseSearchBoxState<T> = BaseSearchBoxState<T>
    > extends BaseSearchUI<T, ChildSearchBoxProps, ChildSearchBoxState> {
    minTagLength: number;
    canAddSuggestion: boolean;
    iOS: boolean;
    scrollSuggestions: boolean;
    dropdownEnabledOnFocus: boolean;
    focusAfterSelect: boolean;
    defaultSuggestions: T[];

    constructor(props: jsx.Props, context: jsx.AppGlobals) {
        super(props, context);
        this.maxSuggestions = 5;
        this.state = {
            ...this.state,
            applyTagToAll: false,
            dropdownEnabled: false,
            allowTagCreationOnInputBlur: false,
        };
        this.minTagLength = 1;
        this.canAddSuggestion = true;
        this.iOS = iOS();
        this.scrollSuggestions = false;
        this.dropdownEnabledOnFocus = false;
        this.focusAfterSelect = true;
        this.defaultSuggestions = [];
    }
    selectSuggestionByOffset(offset) {
        super.selectSuggestionByOffset(offset);
        this.setState({
            applyTagToAll: false,
        });
    }
    selectSuggestionByMouseOver(event, idx) {
        let applyTagToAll;
        if (event.target.className === 'suggestion-apply-all-button') {
            applyTagToAll = true;
        } else {
            applyTagToAll = false;
        }
        this.setState({
            selectedSuggestionIndex: idx,
            applyTagToAll,
        });
    }
    cleanInput(s) {
        return s.replace(/[".]/g, '').replace(/[\s,]+/g, ' ');
    }
    @autobind
    handleOnInput(event) {
        event.preventDefault();
        const s = this.cleanInput(event.target.value);
        this.setState({value: s});
        const reqValue = s.trim();
        this.fetchSuggestions(reqValue).then(this.triggerUpdate);
    }
    @autobind
    handleOnKeyDown(event: KeyboardEvent) {
        super.handleOnKeyDown(event);
        this.setState({dropdownEnabled: true});

        switch (event.keyCode) {
        case KEY.LEFT:
            event.preventDefault();
            this.setState({applyTagToAll: false});
            break;
        case KEY.RIGHT:
            event.preventDefault();
            this.setState({applyTagToAll: true});
            break;
        case KEY.ENTER:
            event.preventDefault();
            this.createTag(event, null);
            break;
        default:
            return;
        }
    }
    @autobind
    handlePaste(event) {
        event.preventDefault();
        const tagsStr = event.clipboardData.getData('Text') as string;
        const tags = tagsStr.split(/[,;#]/).map((tag) => {
            return this.cleanSuggestion(tag);
        });
        this.createTag(null, tags);
    }

    // NOTE: onBlur fires before onInput/onClick so we need to prevent blur
    // actions until other actions can be completed (eg. suggestion click, add
    // tag click, etc).
    @autobind
    handleOnBlur(event) {
        this.setStateSynchronously({allowTagCreationOnInputBlur: true});
        setTimeout(() => {
            if (this.state.allowTagCreationOnInputBlur) {
                this.createTag(null, [this.state.value]);
                this.setState({
                    focused: false,
                    dropdownEnabled: false,
                });
            } else {
                this.setStateSynchronously({
                    allowTagCreationOnInputBlur: true,
                    focused: true,
                });
            }
        }, 200); // NOTE allows time for suggestion selection to register
    }

    @autobind
    handleOnFocus(event) {
        this.scrollInputIntoView();
        this.focus();
    }

    @autobind
    scrollInputIntoView() {
        if (this.props.isMobile && !this.state.focused) {
            // NOTE HACK Android fix: Timeout allows for keyboard to open
            // before scrolling.
            // This is needed for the last tag input field because it is near
            // the bottom of the page and would not otherwise scroll to the top
            // the page.
            const timeout = (this.iOS ? 0 : 200);
            setTimeout(() => {
                if (!this.input) {
                    return;
                }
                const inputPageOffset = this.input.getBoundingClientRect().top +
                    window.pageYOffset;
                const topOffset = 40;
                window.scrollTo({
                    left: 0,
                    top: inputPageOffset - topOffset,
                    behavior: 'smooth',
                });
            }, timeout);
        }
    }
    @autobind
    focus() {
        super.focus();
        this.setState({focused: true});
        if (this.dropdownEnabledOnFocus) {
            this.setState({dropdownEnabled: true});
        }
    }
    @autobind
    blur() {
        this.input.blur();
    }

    getSuggestionListHeader(text: string) {
        const gettextSub = this.context.gtService.gettextSub;
        if (text.length > 0) {
            return gettextSub('SUGGESTED TAGS');
        } else if (!text.length) {
            return gettextSub('FEATURED TAGS');
        }
    }

    @autobind
    handleSuggestionSelect(
        event: InfernoUIEvent<HTMLButtonElement>, idx?: number) {
        this.setState({
            selectedSuggestionIndex: idx,
            allowTagCreationOnInputBlur: false,
        });
        this.createTag(event, null);
    }

    @autobind
    handleSuggestionSelectAll(
        event: InfernoUIEvent<HTMLButtonElement>, idx?: number) {
        this.setState({
            selectedSuggestionIndex: idx,
            allowTagCreationOnInputBlur: false,
            applyTagToAll: true,
        });
        this.createTag(event, null);
    }
    @autobind
    cleanSuggestion(suggestion: string) {
        return suggestion;
    }
    isApplicableToMultipleItems() {
        return false;
    }
    @autobind
    createTag(event, tags: null|string[]) {
        event?.preventDefault?.();
        if (!tags) {
            if (this.state.selectedSuggestionIndex >= 0) {
                tags = [this.valueToString(this.state.suggestions[
                    this.state.selectedSuggestionIndex])];
            } else {
                tags = [this.state.value];
            }
        }
        tags = tags.filter((tag) => {
            return tag.length >= this.minTagLength;
        });
        if (!tags.length) {
            return;
        }

        tags.forEach((tag) => {
            this.onDone(tag);
        });

        this.setState({
            value: '',
            suggestions: this.defaultSuggestions,
            applyTagToAll: false,
            dropdownEnabled: false,
        });
        // NOTE: allows for input re-focus when clicking tag suggestion.
        event && this.focusAfterSelect && this.focus();
    }
    onDone(suggestion: string) {
    }
    renderSuggestionDropDown() {
        const gettextSub = this.context.gtService.gettextSub;
        const text = this.state.value;
        let suggestions: T[] = this.state.suggestions;
        if (!this.scrollSuggestions) {
            suggestions = suggestions.slice(0, this.maxSuggestions);
        }
        const suggestionList = suggestions.map((suggestion: T, i: number) => {
            return <TagSuggestion<T>
                key={suggestion.key()}
                idx={i}
                suggestion={suggestion}
                searchBox={this}
                selectedSuggestionIndex={this.state.selectedSuggestionIndex}
            />;
        });
        const suggestionListHeader = this.getSuggestionListHeader(text);

        return (
            <div className="suggestions-dropdown">
                {suggestions.length > 0 &&
                    <div className="list">
                        {suggestionListHeader && <div
                            className="header"
                        >{ suggestionListHeader }</div>}
                        { suggestionList }
                    </div>
                }
                {this.canAddSuggestion && text.length >= this.minTagLength &&
                    <button
                        className="add-suggestion"
                        onClick={this.handleSuggestionSelect}
                        onMouseOver={this.clearSuggestionSelection}
                    >
                        <div className="text">
                            <div>{gettextSub('Add')}</div>
                            <div>{`${text}`}</div>
                        </div>
                    </button>
                }
            </div>
        );
    }
}

class TagSearchBoxValue implements BaseSearchUIValue {
    tag: string;

    constructor(tag) {
        this.tag = tag;
    }
    key() {
        return this.tag;
    }
    toUserString() {
        return this.tag;
    }
}

interface TagSearchBoxProps extends BaseSearchBoxProps {
    uploadObject: UploadGifDataObject;
    idx: number;
    queue: any[];
}

interface TagSearchBoxState<
    T extends TagSearchBoxValue> extends BaseSearchBoxState<T> {
    selectedSuggestionIndex: number;
}

@subscribe({
    isMobile: ['ui.isMobile'],
})
export class TagSearchBox extends BaseSearchBox<
    TagSearchBoxValue,
    TagSearchBoxProps, TagSearchBoxState<TagSearchBoxValue>> {
    componentDidMount() {
        if (!this.props.isMobile && this.props.idx === 0 &&
            this.props.uploadObject.uploadStatus !== ITEM_STATES.DONE) {
            this.focus();
        }
    }
    stringToValue(s: string): TagSearchBoxValue {
        return new TagSearchBoxValue(s);
    }
    fetchSuggestions(reqValue: string): Promise<TagSearchBoxValue[]> {
        return this.context.apiService.getAutocompleteResults(reqValue)
            .then(({body}) => {
                const suggestions: TagSearchBoxValue[] = [];
                // only update suggestions if search term === current search
                // term.
                if (reqValue === this.state.value.trim()) {
                    for (const item of (body.results || [])) {
                        suggestions.push(this.stringToValue(item));
                    }
                    this.setSuggestions(suggestions);
                }
                return suggestions;
            });
    }
    onDone(suggestion: string) {
        if (this.state.applyTagToAll) {
            this.props.taggingView.addTag(
                suggestion);
        } else {
            this.props.taggingView.addTag(
                suggestion, this.props.uploadObject);
        }
    }
    @autobind
    cleanSuggestion(suggestion: string) {
        if (!suggestion) {
            return '';
        }
        return suggestion.trim();
    }
    @autobind
    placeholder() {
        const gettextSub = this.context.gtService.gettextSub;

        if (this.props.uploadObject.tags.length) {
            return gettextSub('Add More Tags');
        } else {
            return gettextSub('Add Tags (minimum 1)');
        }
    }
    isApplicableToMultipleItems() {
        return this.props.queue.length > 1;
    }
    render() {
        const gettextSub = this.context.gtService.gettextSub;
        const text = this.state.value;
        const shouldRenderSuggestionsDropdown = this.state.dropdownEnabled &&
            this.state.focused;

        return <div className={`TagSearchBox BaseSearchBox${
            this.scrollSuggestions ? ' scrollable' : ''}`}>
            <div className="tag-input-wrapper">
                <input
                    ref={this.setInputElement}
                    id={`upload_tags_${this.props.idx}`}
                    className="tag-input"
                    onInput={this.handleOnInput}
                    onBlur={this.handleOnBlur}
                    onFocus={this.handleOnFocus}
                    onKeyDown={this.handleOnKeyDown}
                    onMouseOver={this.clearSuggestionSelection}
                    onPaste={this.handlePaste}
                    value={text}
                    placeholder={this.placeholder()}
                    spellCheck={false}
                    // NOTE When a user creates a tag, the html input is
                    // cleared but value stored in the ios keyboard is not.
                    // If the user starts typing a new tag, the keyboard will
                    // append that text to the already created tag when
                    // suggesting an "autocorrect" value. The only effective
                    // method I found for resetting the keyboard value was to
                    // blur the input -- this creates other issues wrt
                    // scrolling and keyboard collapsing/reappearing.
                    autoCorrect={this.iOS ? 'off' : 'on'}
                    autoCapitalize="off"
                    autoComplete="off"
                />
                {(this.isApplicableToMultipleItems() && text?.length >= 2 &&
                    this.state.selectedSuggestionIndex < 0) &&
                    <button
                        className={`tag-input-apply-all-button ${
                            this.state.applyTagToAll ? ' selected' : ''}`}
                        onClick={this.handleSuggestionSelectAll}
                    >
                        {
                            // Translators: For adding tag to all GIFs.
                            gettextSub('Add to All')
                        }
                    </button>
                }
            </div>
            { shouldRenderSuggestionsDropdown &&
                this.renderSuggestionDropDown() }
        </div>;
    }
}
