import {autobind} from 'core-decorators';

import emitter from '../util/emitter';
import {BaseService} from './base';


export class GoogleAuthService extends BaseService {
    TENOR_SCOPE: string;
    scriptLoaded: boolean;
    errorMsg: string|null;

    constructor(context: jsx.AppGlobals) {
        super(context, {});
        this.TENOR_SCOPE = 'https://www.googleapis.com/auth/tenor';
        this.scriptLoaded = false;
        this.errorMsg = null;
    }

    getClientConfig() {
        // NOTE params for gapi.auth2.init
        // https://developers.google.com/identity/sign-in/web/reference#gapiauth2clientconfig
        return {
            client_id: this.context.CONSTANTS.GOOGLE_SIGNIN_CLIENT_ID,
            scope: `email ${this.TENOR_SCOPE}`, // TODO profile|email|openid
            fetch_basic_profile: false, // NOTE change to true to allow access to profile image, name, etc
        };
    }
    // NOTE https://developers.google.com/identity/sign-in/web/reference#gapiauth2signinoptions
    getSignInOptions() {
        return {
            prompt: 'select_account',
            scope: 'email',
        };
    }
    load() {
        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.async = true;
        script.onload = this.loadGoogleAuth;
        script.onerror = () => {
            this.errorMsg = 'Google Auth script failed to load.';
            emitter.emit('googleAuthLoadChange');
        };
        script.src = 'https://apis.google.com/js/client:platform.js';

        const scriptEl = document.getElementsByTagName('script')[0];
        scriptEl?.parentNode?.insertBefore(script, scriptEl);
    }
    @autobind
    loadGoogleAuth() {
        window.gapi.load('auth2', () => {
            console.log('window.gapi.auth2', window.gapi.auth2,
                this.getClientConfig());
            window.gapi.auth2.init(this.getClientConfig())
                .then(() => {
                    this.scriptLoaded = true;
                    emitter.emit('googleAuthLoadChange');
                }, (error: Error) => {
                    this.errorMsg = error.toString();
                    console.error(this.errorMsg);
                    emitter.emit('googleAuthLoadChange');
                });
        });
    }
    signinDialogWindow() {
        const GoogleAuth = window.gapi.auth2.getAuthInstance();
        console.log('signinDialogWindow GoogleAuth', GoogleAuth);
        return GoogleAuth.signIn(this.getSignInOptions())
            .then((GoogleUser) => {
                return {GoogleUser};
            });
    }
    signOut() {
        const GoogleAuth = window.gapi.auth2.getAuthInstance();
        console.log('signOut GoogleAuth', GoogleAuth);
        return GoogleAuth.signOut();
    }
}
