function isTagListBody(
    body: api.UnknownBody): body is api.TagListBody { // eslint-disable-line @typescript-eslint/no-unused-vars
    return 'results' in body && typeof body.results[0] === 'string';
}

function isMedia(obj: any): obj is api.Media {
    return 'url' in obj;
}

function isMediaFormats(obj: any): obj is api.MediaFormats {
    return obj && 'gif' in obj;
}

function isCollectionListBody(
    body: api.UnknownBody): body is api.CollectionListBody {
    return 'collections' in body;
}

function isPostListBody(body: api.UnknownBody): body is api.PostListBody {
    return 'results' in body && body.results[0] && body.results[0]['id'];
}

export class ResponseAndBodyError extends Error {
    response: Response|null;
    body: any;

    constructor(response: Response|null, body: any, cause: Error) {
        super('Error occurred during fetch.', {cause});
        this.response = response;
        this.body = body;
    }
}

export type ResponseAndBody<T> = {response: Response, body: T};

/**
 * Converts xhr to an object like we would get from fetch.
 */
function xhrToFetchResponse(xhr: XMLHttpRequest): Response {
    const headers = new Headers();
    xhr.getAllResponseHeaders().trim().split(/[\r\n]+/).forEach((line) => {
        if (line) {
            const [header, val] = line.split(': ', 2);
            headers.append(header, val);
        }
    });

    return new Response(xhr.responseText, {
        headers,
        status: xhr.status,
        statusText: xhr.statusText,
    });
}

/**
 * This callback type is called `requestCallback` and is displayed as a global
 * symbol.
 */
type onprogressCallback = (
    ev: ProgressEvent<EventTarget>,
    ) => any;

type XhrFetchParams = {
    url: string;
    method: string;
    data: File;
    headers: Headers;
    progressCB?: onprogressCallback;
};

function xhrFetch({url, method, data, headers, progressCB}: XhrFetchParams):
    Promise<Response> {
    return new Promise<Response>((resolve, reject) => {
        const xhr = new XMLHttpRequest();
        xhr.timeout = TIMEOUT_MILLIS;
        // https://g3doc.corp.google.com/uploader/g3doc/customer/customer_config.md?cl=head#enable-multipart-parsing
        xhr.upload.onprogress = progressCB;
        xhr.onload = () => {
            resolve(xhrToFetchResponse(xhr));
        };
        xhr.onerror = (err: ProgressEvent) => {
            reject(new Error('API error', {cause: err}));
        };
        xhr.ontimeout = () => {
            reject(new Error('Request timeout'));
        };
        xhr.open('POST', url);
        for (const [key, val] of headers.entries()) {
            xhr.setRequestHeader(key, val);
        }
        try {
            xhr.send(data);
        } catch (err) {
            reject(new Error('Send error', {cause: err}));
        }
    });
}

function cleanGifListResponse({body, response}: ResponseAndBody<any>):
    ResponseAndBody<any> {
    if (isPostListBody(body)) {
        body = body as api.PostListBody;
        const ary = [];

        loop1:
        for (const gif of body.results) {
            if (isMediaFormats(gif.media_formats)) {
                // delete unused attributes to save on memory/page size
                delete gif.sticker;
                delete gif.content_rating;
                delete gif.composite;
                delete gif.primary_term;
                const mediaF = gif.media_formats as api.MediaFormats;
                for (const [format, media] of Object.entries(mediaF)) {
                    if (!isMedia(media)) {
                        continue;
                    }
                    if (!media.dims) {
                        console.warn(
                            `${format} missing dims, skipping gif: ${gif.id}`);
                        continue loop1;
                    }
                }
                // Fix for missing tinygif in v2.
                if (!mediaF.tinygif) {
                    mediaF.tinygif = mediaF.mediumgif || mediaF.gif;
                }
                if (mediaF.tinygif && !mediaF.tinywebp) {
                    mediaF.tinywebp = {...mediaF.tinygif};
                }
                if (mediaF.tinygif_transparent &&
                        !mediaF.tinywebp_transparent) {
                    mediaF.tinywebp_transparent = {
                        ...mediaF.tinygif_transparent};
                }
                ary.push(gif);
            }
        }
        body.results = ary;
    }

    return {body, response};
}

function getComponent(): string {
    return (iOS() ?
        'web_mobile_ios' : isMobile() ?
            'web_mobile' : 'web_desktop');
}

export function setFlags(body: Record<string, boolean>, flags: string[]) {
    for (const flag of flags) {
        if (flag) {
            body[flag.replace('!', '')] = !flag.startsWith('!');
        }
    }
}

function fixResponse<ResponseBodyType>(resolve, reject) {
    return function fixResponseInner(
        response: Response): Promise<ResponseAndBody<ResponseBodyType>> {
        // Our API doesn't return the correct HTTP status
        // codes on error so we need to check "successful"
        // API calls for errors.
        return response.text().then(function fixResponseTextThen(
            bodyStr: string) {
            let body = {body: bodyStr} as api.UnknownBody;
            let cause;
            if (bodyStr.length && response.headers.get(
                'content-type').startsWith('application/json')) {
                try {
                    body = JSON.parse(bodyStr) as api.UnknownBody;
                } catch (err) {
                    cause = err;
                    body = {
                        error: `JSON parsing failed: ${err}`,
                    } as api.ErrorBody;
                }
                if ((body as api.ErrorBody).error) {
                    reject(new ResponseAndBodyError(response, body, cause));
                    return;
                }
            }
            if (response.ok) {
                resolve({
                    response,
                    body: body as ResponseBodyType,
                });
            } else {
                // NOTE: (v2 API): need to ensure proper error handling for
                // future endpoints v2 has the correct HTTP status codes on
                // error but returns a different error object in the
                // body --> error: {code, status, message, details}
                if ((body as api.NonStandardErrorBody).error?.message) {
                    body = {
                        error: (
                            body as api.NonStandardErrorBody).error.message,
                    } as api.ErrorBody;
                }
                reject(new ResponseAndBodyError(response, body, cause));
            }
        });
    };
}

