    getV2<ResponseBodyType extends api.UnknownBody=api.UnknownBody>(
        path: string,
        params?: object,
        headers?: Headers): Promise<ResponseAndBody<ResponseBodyType>> {
        return this.requestV2<ResponseBodyType>(
            'GET', path, params, null, headers);
    }
