export const PATH = '';


class App extends BaseApp {
    fixContext() {
        addLanguagesToContext(this.context);
    }
    beforeChildren() {
        if (process.env.BROWSER) {
            let chosenLocale = getChosenLocale(this.context);
            if (!chosenLocale) {
                const navLang = window.navigator.language.replace('-', '_');
                const exactLang = this.context.languages.find((language) => {
                    return language[0] === navLang;
                });
                if (exactLang) {
                    chosenLocale = exactLang[0];
                } else {
                    const navLangBase = navLang.split('_')[0];
                    const baseLang = this.context.languages.find((language) => {
                        return language[0] === navLangBase;
                    });
                    if (baseLang) {
                        chosenLocale = baseLang[0];
                    } else {
                        chosenLocale = 'en';
                    }
                }
                setChosenLocale(this.context, chosenLocale);
            }
            if (chosenLocale !== this.context.gtService.gt.locale) {
                redirectToLang(this.context, chosenLocale);
            }
        }

        const currentPath = this.context.gtService.delocalizeUrlPath(
            this.context.router.history.location.pathname);
        const showNav = [
            '/imessage',
        ].indexOf(currentPath) === -1;
        const showSearch = [
            '/about-us',
            '/partners',
            '/contentpartners',
            '/imessage',
            '/gif-maker',
        ].indexOf(currentPath) === -1 && !currentPath.includes('/developer');

        return [
            this.allowBanners && <TOSBanner/>,
            <LanguageBanner />,
            showNav && <NavBar/>,
            showSearch && <TopSearchBar/>,
        ];
    }
    afterChildren() {
        return (<DialogContainer
            dialogMap={{
                'auth-dialog': {
                    'class': AuthDialog,
                    'options': {
                        'favoriting': true,
                        'signupAllowed': true,
                        'getLoggedInURL': () => {
                            return this.linkToProfile();
                        },
                        'expiredSession': false,
                        'forceLogInToUpload': false,
                        'loggedinCallback': undefined,
                        'uploadQueue': undefined,
                    },
                },
                'flagging': {'class': FlaggingDialog},
                'edit-profile-dialog': {
                    'class': EditProfileDialog,
                },
                'confirmation-dialog': {
                    'class': ConfirmationDialog,
                    'options': {
                        'isBlockingDialog': true,
                    },
                    'style': {
                        'width': '440px',
                        'max-width': '100%',
                        'padding': '24px',
                    },
                },
                'caption-share-dialog': {
                    'class': CaptionShareDialog,
                },
                'language-selection-dialog': {
                    'class': LanguageSelectionDialog,
                },
                'static-image-dialog': {
                    'class': StaticImageDialog,
                },
                'popup-dialog': {
                    'class': PopupDialog,
                },
                'popup-dialog-blank': {
                    'class': PopupDialog,
                },
            }}
        />);
    }
}


/**
 *
 * @param appGlobals
 */
function routesForLocale(appGlobals) {
    const gtService = appGlobals.gtService;
    const pgettext = gtService.gt.pgettext.bind(gtService.gt);

    let pathPrefix = `/${PATH}`;
    const locale = gtService.gt.locale;
    if (locale && locale !== 'en') {
        pathPrefix = `/${gtService.getLocaleUrlPrefix()}${pathPrefix}`;
    }
    // We need a mapping so we can untranslate paths if needed.
    // This needs to be a function so translating happens on the fly, instead of
    // getting hard coded as one language.
    const pathMap = {
        'gif-maker':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'gif-maker'),
        'search':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'search'),
        'view':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'view'),
        'reactions':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'reactions'),
        'explore':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'explore'),
        'users':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'users'),
        'official':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'official'),
        'packs':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'packs'),
        'collections':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'collections'),
        'emotional-graph':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'emotional-graph'),
        'partners':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'partners'),
        'contentpartners':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'contentpartners'),
        'about-faq':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'about-faq'),
        'about-us':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'about-us'),
        'imessage':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'imessage'),
        'contact':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'contact'),
        'legacy-account-recover':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legacy-account-recover'),
        'legal-terms':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legal-terms'),
        'legal-terms-update':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legal-terms-update'),
        'legal-terms-developer-update':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legal-terms-developer-update'),
        'legal-privacy':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legal-privacy'),
        'legal-privacy-update':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legal-privacy-update'),
        'legal/privacy':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legal/privacy'),
        'legal/data-usage':
            // Translators: Leave this URL path component untranslated.
            pgettext('url path component', 'legal/data-usage'),
    };
    // This disables translations for url path components.
    for (const path of Object.keys(pathMap)) {
        pathMap[path] = path;
    }
    gtService.setLocalizedPaths(pathMap);

    return <App appGlobals={appGlobals}><Switch>
        <Route exact={true} path={pathPrefix} component={ FeaturedPage }/>
        <Route path={`${pathPrefix}${pathMap['gif-maker']}`} component={ GifMakerPage }/>
        <Route path={`${pathPrefix}${pathMap['search']}/:searchData`} component={ SearchPage }/>
        <Route path={`${pathPrefix}${pathMap['search']}/`} component={ SearchPage }/>
        <Route path={`${pathPrefix}${pathMap['view']}/:id`} component={ GifPage }/>
        <Route path={`${pathPrefix}${pathMap['reactions']}`} component={ ReactionsPage }/>
        <Route path={`${pathPrefix}${pathMap['explore']}/:searchData`} component={ ExplorePage }/>
        <Route path={`${pathPrefix}${pathMap['explore']}`} component={ ExploreHomePage }/>
        <Route path={`${pathPrefix}${pathMap['users']}/:username/:mediatype?`} component={ UserProfilePage }/>
        <Route path={`${pathPrefix}${pathMap['official']}/:username/:mediatype?`} component={ BrandedPartnerPage }/>
        <Route path={`${pathPrefix}${pathMap['packs']}/:id`} component={ PackPage }/>
        <Route path={`${pathPrefix}${pathMap['collections']}/:id`} component={ CollectionPage }/>
        <Route path={`${pathPrefix}${pathMap['emotional-graph']}`} component={ EmotionalGraphPage }/>
        <Route path={`${pathPrefix}${pathMap['partners']}`} component={ PartnerSpotlightPage }/>
        <Route path={`${pathPrefix}${pathMap['contentpartners']}`} component={ PartnerSpotlightPage }/>
        <Route path={`${pathPrefix}${pathMap['about-faq']}`} component={ AboutFAQPageRedirect }/>
        <Route path={`${pathPrefix}${pathMap['about-us']}`} component={ AboutUsRedirect }/>
        <Route path={`${pathPrefix}${pathMap['imessage']}`} component={ IMessagePage }/>
        <Route path={`${pathPrefix}${pathMap['contact']}`} component={ ContactPageRedirect }/>
        <Route path={`${pathPrefix}${pathMap['legacy-account-recover']}`} component={ LegacyAccountRecoverPage }/>
        <Route path={`${pathPrefix}${pathMap['legal-terms']}`} component={ LegalTermsPage }/>
        <Route path={`${pathPrefix}${pathMap['legal-terms-update']}`} component={ LegalTermsUpdateRedirect }/>
        <Route path={`${pathPrefix}${pathMap['legal-terms-developer-update']}`} component={ LegalTermsDeveloperUpdateRedirect }/>
        <Route path={`${pathPrefix}${pathMap['legal-privacy']}`} component={ LegalPrivacyRedirect }/>
        <Route path={`${pathPrefix}${pathMap['legal-privacy-update']}`} component={ LegalPrivacyRedirect }/>
        {/**
         * Frank had us set these 2 URLs up, it's linked to from an LG product.
         */}
        <Route path={`${pathPrefix}${pathMap['legal/privacy']}`} component={ LegalPrivacyRedirect }/>
        <Route path={`${pathPrefix}${pathMap['legal/data-usage']}`} component={ LGLegalDataUsagePage }/>
        <Route path="/:shortId*.gif" component={ GifPage }/>
        <Route path="*" component={ HTTP404Page }/>
    </Switch></App>;
}


/**
 *
 * @param history
 * @param config
 * @param request
 * @param response
 * @param {jsx.AppGlobals} context
 */
export function routes(history, config, request, response, context) {
    const appGlobals = initConfig(config, PATH, request, response);
    appGlobals.store.register('ui.dataSaverMode', DataSaverModeDataSource);
    appGlobals.store.register('ui.isMobile', IsMobileDataSource);
    appGlobals.store.register('ui.gifSizes.*', GifImgSizesDataSource);
    appGlobals.store.set('ui.dataSaverMode', true);

    if (context) {
        Object.assign(context, appGlobals);
        for (const [key, val] of Object.entries(appGlobals)) {
            context[key] = val;
        }
    }
    setupAnalytics({context});

    if (process.env.BROWSER) {
        history.listen(function() {
            appGlobals.apiService.newApirefid();
        });

        window.addEventListener('load', function() {
            const {saveData, effectiveType} = (window.navigator['connection'] || {saveData: undefined, effectiveType: undefined});
            window.gaEvent({
                category: 'network-speed',
                action: 'window.navigator.connection.saveData',
                label: saveData,
            });
            window.gaEvent({
                category: 'network-speed',
                action: 'window.navigator.connection.effectiveType',
                label: effectiveType,
            });
            let dataSaverMode = false;
            let dataSaverModeRationale = '';
            if (saveData) {
                dataSaverMode = true;
                dataSaverModeRationale = 'saveData';
            } else if (effectiveType && (effectiveType.endsWith('2g') || effectiveType.endsWith('3g'))) {
                dataSaverMode = true;
                dataSaverModeRationale = 'effectiveType';
            } else if (Date.now() - context.CONSTANTS.START_TS > 3000) {
                dataSaverMode = true;
                dataSaverModeRationale = 'window.load speed';
            }
            window.gaEvent({
                category: 'network-speed',
                action: 'dataSaverModeRationale',
                label: dataSaverModeRationale,
            });
            request.console.log('dataSaverMode', dataSaverMode);
            if (!dataSaverMode) {
                appGlobals.store.set('ui.dataSaverMode', dataSaverMode);
            }
        });
    }

    return getRouter(routesForLocale(appGlobals), history);
}

// Render HTML if in the browser
runIfInBrowser(routes, lazyLoadComponent.promises);
