import {DataSource} from '../../replete';
import {MyDataSource} from './datasources';
import {isMobile} from './util';

export class ProfilePageDataSource extends MyDataSource {
    key([username]) {
        return username;
    }
    getInitial([username]) {
        const val = {section: 'profile'};
        this.set([username], val);
        return val;
    }
}

export class GifMakerPageDataSource extends MyDataSource {
    constructor(store: app.MyStore, path: string) {
        super(store, path);
        this.reset();
    }

    defaultSettings() {
        return {
            makerPage: null,
            imagePanelBoundingRect: null,
            view: 'upload',
            itemPageCaptioning: {
                status: false,
                gif: null,
            },
            queueIdx: 0,
        };
    }
    key([prop]) {
        return prop;
    }

    reset() {
        this.console.debug('reset');
        for (const [k, v] of Object.entries(this.defaultSettings())) {
            this.console.debug('resetting', k, v);
            this.set([k], v);
        }
    }

    getInitial([prop]) {
        this.console.debug('getInitial', prop);
        const val = this.defaultSettings()[prop];
        this.set([prop], val);
        return val;
    }
}

export class GifEditorDataSource extends MyDataSource {
    constructor(store: app.MyStore, path: string) {
        super(store, path);
        this.reset();
    }

    defaultSettings() {
        return {
            editor: null,
            editorBoundingRect: null,
            editorProgress: {},
            encodingStatus: false,
            allowCaptionAutoRepositioning: false, // TODO rename
            tool: null,

            editorToolsUsageTracking: {}, // 'tr' -> trim, 'cr' -> crop, 'ca' -> caption
            trimToolUsageTracking: {
                actions: {}, // ('ui'\'num')
            },
            cropToolUsageTracking: {
                actions: {}, // ('ui'\'num')
                info: null, // eg. '16_9' aspect ratio
            },
            captionToolUsageTracking: {
                actions: {}, // ('ui'\'num')
            },

            captionLayers: [],

            captionData: {
                captionText: '',
                captionFontSize: 32,
                captionColor: '#FFFFFF', // white
                captionCoords: null, // [[x0, y0], [x1, y1]]
                captionCanvasWidth: null,
                captionCanvasHeight: null,
                captionCanvasCroppedWidth: null,
                captionCanvasCroppedHeight: null,
                captionMoved: false,
                captionResized: false,
            },

            cropData: {
                cropCoords: null, // [[x0, y0], [x1, y1]]
                cropRatio: false,
                isCropped: false,
            },

            trimData: {
                paused: false,
                startFrameIdx: 0,
                endFrameIdx: 0,
                frameRange: [0, 0],
            },

            trimDataCurrentFrameIdx: 0,
        };
    }

    reset() {
        this.set(this.defaultSettings());
    }

    getInitial([arg]) {
        return [];
    }
}

export class IsMobileDataSource extends MyDataSource {
    // a bug in replete requires everything to have a DataSource
    constructor(store: app.MyStore, path: string) {
        super(store, path);
        this.set(isMobile());
        window?.addEventListener?.('resize', this.update.bind(this));
    }

    getInitial() {
        return isMobile();
    }

    update() {
        const next = isMobile();
        const prev = this.get([]);
        if (next !== prev) {
            this.set(next);
            return next;
        }
        return prev;
    }
}
